View.TextArea:
module.exports = {
  purge: {
    mode: 'all',
    method: 'sync',
    options: {
      missing: true,
      widgets: false,
      safelist: [],
      plugins: []
    }
  },
  theme: {
    extend: {},
    // Ti Elements, IDs, classes...
  }
}

// Replaces ALL default opacity values
theme: {
  opacity: {
    15: '0.15', 35: '0.35',
    65: '0.65', 85: '0.85'
  }
}

// Adds 'primary' but keeps all defaults
theme: {
  extend: {
    colors: {
      primary: '#002359'
    }
  }
}
// → bg-primary, text-primary, border-primary

extend: {
  colors: {
    tahiti: {
      100: '#cffafe', 200: '#a5f3fc',
      500: '#06b6d4', 800: '#155e75'
    }
  }
}
// → bg-tahiti-100, text-tahiti-500, etc.

extend: {
  colors: {
    surface: {
      DEFAULT: 'surfaceColor',
      high: 'surfaceHighColor'
    },
    'on-surface': 'textColor',
    accent: 'accentColor'
  }
}
// → bg-surface, bg-surface-high, text-on-surface

theme: {
  spacing: {
    sm: 8, md: 12, lg: 16, xl: 24
  }
}
// → m-sm, m-md, w-lg, h-xl, gap-sm, etc.

theme: {
  extend: {
    spacing: {
      72: '18rem', 84: '21rem', 96: '24rem'
    }
  }
}
// → m-72, w-84, h-96 (added to defaults)
